mapper.update:
UPDATE task_review
SET score   = #{score},
    `comment` = #{comment}
WHERE id = #{id}
  AND deleted = 0

mapper.select:
SELECT 
FROM task_review r

    r.deleted = 0

        AND r.submission_id = #{submissionId}


        AND r.reviewer_id = #{reviewerId}

SELECT 
FROM task_review r
         JOIN task_submission s ON s.id = r.submission_id

    AND r.deleted = 0
    AND s.user_id = #{userId}

        AND r.submission_id = #{submissionId}

SELECT 
FROM task_review r

    AND r.deleted = 0
    AND r.reviewer_id = #{userId}

        AND r.submission_id = #{submissionId}


        AND r.reviewer_id = #{reviewerId}
